INSERT INTO `config_info` VALUES (1,'gateway.yml','DEFAULT_GROUP','spring:\n  cloud:\n    gateway:\n      globalcors:\n        # 跨域\n        cors-configurations:\n          \"[/**]\":\n            allowed-origin-patterns: \"*\"\n            allowed-headers: \"*\"\n            allowed-methods: \"*\"\n      routes:\n        - id: auth-routes\n          uri: lb://auth-service\n          predicates:\n            - Path=/auth/**\n          filters:\n            - name: JwtAuthentication\n              args:\n                excludePath:\n                  - /auth/test\n                  - /auth/login\n                  - /auth/register\n                  - /auth/v3/api-docs\n        - id: seckill-routes\n          uri: lb://seckill-service\n          predicates:\n            - Path=/seckill/**\n          filters:\n            - name: JwtAuthentication\n              args:\n                excludePath:\n                  - /seckill/v3/api-docs\n                  - /seckill/test\nknife4j:\n  gateway:\n    enabled: true\n    # 指定服务发现的模式聚合微服务文档，并且是默认`default`分组\n    strategy: discover\n    discover:\n      enabled: true\n      # 指定版本号(Swagger2|OpenAPI3)\n      version : openapi3\n      # 需要排除的微服务(eg:网关服务)\n      excluded-services:\n        - gateway\n\n','03d1404cedfc80b770fce1b85cc50846','2025-06-11 22:49:35','2025-06-14 19:52:04','nacos','172.29.0.1','','d53d08fa-7aab-4b26-975d-410cfc15983b','','','','yaml','',''),(4,'redis-config.yml','EXT_GROUP','spring:\r\n  data:\r\n    redis:\r\n      host: localhost\r\n      password: 123456\r\n      port: 6379\r\n      lettuce:\r\n        pool:\r\n          max-active: 50 #连接池最大连接数（使用负值表示没有限制）\r\n          max-wait: 3000 #连接池最大阻塞等待时间（使用负值表示没有限制）\r\n          max-idle: 20   #连接池中的最大空闲连接\r\n          min-idle: 10    #连接池中的最小空闲连接\r\n        shutdown-timeout: 1s  # 关闭客户端连接之前等待任务处理完成的最长时间\r\n      timeout: 5000   #redis连接超时时间（毫秒）','00adcb57553d772ac38803c2a36b25da','2025-06-11 23:05:11','2025-06-11 23:05:11',NULL,'172.29.0.1','','d53d08fa-7aab-4b26-975d-410cfc15983b',NULL,NULL,NULL,'yaml',NULL,''),(5,'rabbitmq-config.yml','EXT_GROUP','spring:\n  rabbitmq:\n    virtual-host: /\n    username: admin\n    password: admin\n    addresses: localhost:5672\n    listener:\n      simple:\n        concurrency: 4 # 4个消费者对应4个线程\n        max-concurrency: 8\n        prefetch: 10 # 每个消费者每次监听时可拉取处理的消息数量（一次处理消费数）\n        acknowledge-mode: auto\n        default-requeue-rejected: true # 消息处理失败重新入队\n        retry:\n          enabled: true # 开启消费者失败重试\n          initial-interval: 1000ms # 初始的失败等待时长为1秒\n          multiplier: 1 # 失败的等待时长倍数，下次等待时长 = multiplier * last-interval（类似csma-cd）\n          max-attempts: 3 # 最大重试次数\n          stateless: false # true无状态；false有状态。如果业务中包含事务，这里改为false\n    publisher-confirm-type: correlated # 保证消息到交换机\n    publisher-returns: true # 不可路由到队列的消息，回退\n','e29186eb167ff638d5dafba89777b78f','2025-06-11 23:06:11','2025-06-12 12:31:48',NULL,'172.29.0.1','','d53d08fa-7aab-4b26-975d-410cfc15983b','','','','yaml','',''),(11,'dao.yml','EXT_GROUP','spring:\r\n  datasource:\r\n    driver-class-name: com.mysql.cj.jdbc.Driver\r\n    password: 123456\r\n    url: jdbc:mysql://localhost:3306/seckill?serverTimezone=Asia/Shanghai&useUnicode=true&characterEncoding=utf-8&allowPublicKeyRetrieval=true&useSSL=false\r\n    username: root\r\n\r\nmybatis:\r\n  mapper-locations: classpath:mapper/*.xml\r\n  type-aliases-package: com.lzh.entity\r\n\r\n','e2576fc179f4d0da0b49d59c919c17a9','2025-06-13 20:03:36','2025-06-13 20:03:36','nacos','172.29.0.1','','d53d08fa-7aab-4b26-975d-410cfc15983b',NULL,NULL,NULL,'yaml',NULL,''),(12,'auth-service.yml','DEFAULT_GROUP','# springdoc-openapi项目配置\nspringdoc:\n  swagger-ui:\n    path: /swagger-ui.html\n    tags-sorter: alpha\n    operations-sorter: alpha\n  api-docs:\n    path: /v3/api-docs\n  group-configs:\n    - group: \'default\'\n      paths-to-match: \'/**\'\n      packages-to-scan: com.lzh.controller\n# knife4j的增强配置，不需要增强可以不配\nknife4j:\n  enable: true\n  setting:\n    language: zh_cn\n','71277a97bdb14adfccf95d367c9f5b85','2025-06-13 20:06:05','2025-06-14 19:41:02','nacos','172.29.0.1','','d53d08fa-7aab-4b26-975d-410cfc15983b','','','','yaml','',''),(13,'seckill-service.yml','DEFAULT_GROUP','# springdoc-openapi项目配置\nspringdoc:\n  swagger-ui:\n    path: /swagger-ui.html\n    tags-sorter: alpha\n    operations-sorter: alpha\n  api-docs:\n    path: /v3/api-docs\n  group-configs:\n    - group: \'default\'\n      paths-to-match: \'/**\'\n      packages-to-scan: com.lzh.controller\n# knife4j的增强配置，不需要增强可以不配\nknife4j:\n  enable: true\n  setting:\n    language: zh_cn\n','71277a97bdb14adfccf95d367c9f5b85','2025-06-13 20:06:51','2025-06-14 18:56:04','nacos','172.29.0.1','','d53d08fa-7aab-4b26-975d-410cfc15983b','','','','yaml','','');
