INSERT INTO `his_config_info` VALUES (0,1,'gateway.yml','DEFAULT_GROUP','','spring:\r\n    cloud:\r\n        gateway:\r\n        globalcors:\r\n            # 配置跨域\r\n            cors-configurations:\r\n            \'[/**]\':\r\n                allowed-origin-patterns: \"*\"\r\n                allowed-headers: \"*\"\r\n                allowed-methods: \"*\"\r\n        routes:\r\n        - id: seckill-routes\r\n            uri: lb://seckill-service\r\n            predicates:\r\n            - Path=/seckill/**\r\n            filters:\r\n            - RewritePath=/seckill/?(?<segment>.*), /$\\{segment} #  路径重写：去掉路径中的 /seckill','470fc575ce9a955ca302a45c4fbd2c2c','2025-06-11 22:49:35','2025-06-11 22:49:35',NULL,'172.29.0.1','I','d53d08fa-7aab-4b26-975d-410cfc15983b',''),(1,2,'gateway.yml','DEFAULT_GROUP','','spring:\r\n    cloud:\r\n        gateway:\r\n        globalcors:\r\n            # 配置跨域\r\n            cors-configurations:\r\n            \'[/**]\':\r\n                allowed-origin-patterns: \"*\"\r\n                allowed-headers: \"*\"\r\n                allowed-methods: \"*\"\r\n        routes:\r\n        - id: seckill-routes\r\n            uri: lb://seckill-service\r\n            predicates:\r\n            - Path=/seckill/**\r\n            filters:\r\n            - RewritePath=/seckill/?(?<segment>.*), /$\\{segment} #  路径重写：去掉路径中的 /seckill','470fc575ce9a955ca302a45c4fbd2c2c','2025-06-11 22:51:18','2025-06-11 22:51:19',NULL,'172.29.0.1','U','d53d08fa-7aab-4b26-975d-410cfc15983b',''),(0,3,'seckill-service','DEFAULT_GROUP','','mybatis:\r\n  type-aliases-package: com.lzh.entity\r\n  mapper-locations: classpath:mapper/*.xml','d7dcb6cd9ee57e895c9de07c3beb6d86','2025-06-11 22:54:34','2025-06-11 22:54:35',NULL,'172.29.0.1','I','d53d08fa-7aab-4b26-975d-410cfc15983b',''),(1,4,'gateway.yml','DEFAULT_GROUP','','spring:\n    cloud:\n        gateway:\n        globalcors:\n            cors-configurations:\n            \'[/**]\':\n                allowed-origin-patterns: \"*\"\n                allowed-headers: \"*\"\n                allowed-methods: \"*\"\n        routes:\n        - id: seckill-routes\n            uri: lb://seckill-service\n            predicates:\n            - Path=/seckill/**\n            filters:\n            - RewritePath=/seckill/?(?<segment>.*), /$\\{segment} ','8f336c060f219d1d7298a2eebef08630','2025-06-11 22:57:25','2025-06-11 22:57:26',NULL,'172.29.0.1','U','d53d08fa-7aab-4b26-975d-410cfc15983b',''),(2,5,'seckill-service','DEFAULT_GROUP','','mybatis:\r\n  type-aliases-package: com.lzh.entity\r\n  mapper-locations: classpath:mapper/*.xml','d7dcb6cd9ee57e895c9de07c3beb6d86','2025-06-11 23:00:54','2025-06-11 23:00:54',NULL,'172.29.0.1','U','d53d08fa-7aab-4b26-975d-410cfc15983b',''),(2,6,'seckill-service','DEFAULT_GROUP','','spring:\n  datasource:\n    username: root\n    password: 123456\n    url: jdbc:mysql://localhost:3306/seckill?serverTimezone=Asia/Shanghai&useUnicode=true&characterEncoding=utf-8&allowPublicKeyRetrieval=true&useSSL=false\n    driver-class-name: com.mysql.cj.jdbc.Driver\n\nmybatis:\n  type-aliases-package: com.lzh.entity\n  mapper-locations: classpath:mapper/*.xml\n','c7c068c82d1442297131beb737d1f262','2025-06-11 23:03:04','2025-06-11 23:03:04',NULL,'172.29.0.1','D','d53d08fa-7aab-4b26-975d-410cfc15983b',''),(0,7,'seckill-service.yml','DEFAULT_GROUP','','spring:\r\n  datasource:\r\n    username: root\r\n    password: 123456\r\n    url: jdbc:mysql://localhost:3306/seckill?serverTimezone=Asia/Shanghai&useUnicode=true&characterEncoding=utf-8&allowPublicKeyRetrieval=true&useSSL=false\r\n    driver-class-name: com.mysql.cj.jdbc.Driver\r\n\r\nmybatis:\r\n  type-aliases-package: com.lzh.entity\r\n  mapper-locations: classpath:mapper/*.xml\r\n','c884eff8589f79e7809aa457c67a4629','2025-06-11 23:03:19','2025-06-11 23:03:19',NULL,'172.29.0.1','I','d53d08fa-7aab-4b26-975d-410cfc15983b',''),(0,8,'redis-config.yml','EXT_GROUP','','spring:\r\n  data:\r\n    redis:\r\n      host: localhost\r\n      password: 123456\r\n      port: 6379\r\n      lettuce:\r\n        pool:\r\n          max-active: 50 #连接池最大连接数（使用负值表示没有限制）\r\n          max-wait: 3000 #连接池最大阻塞等待时间（使用负值表示没有限制）\r\n          max-idle: 20   #连接池中的最大空闲连接\r\n          min-idle: 10    #连接池中的最小空闲连接\r\n        shutdown-timeout: 1s  # 关闭客户端连接之前等待任务处理完成的最长时间\r\n      timeout: 5000   #redis连接超时时间（毫秒）','00adcb57553d772ac38803c2a36b25da','2025-06-11 23:05:10','2025-06-11 23:05:11',NULL,'172.29.0.1','I','d53d08fa-7aab-4b26-975d-410cfc15983b',''),(0,9,'rabbitmq-config.yml','EXT_GROUP','','spring:\r\n  rabbitmq:\r\n    virtual-host: /\r\n    username: admin\r\n    password: admin\r\n    addresses: ${docker.service.rabbitmq}:5672\r\n    listener:\r\n      simple:\r\n        concurrency: 4 # 4个消费者对应4个线程\r\n        max-concurrency: 8\r\n        prefetch: 10 # 每个消费者每次监听时可拉取处理的消息数量（一次处理消费数）\r\n        acknowledge-mode: auto\r\n        default-requeue-rejected: true # 消息处理失败重新入队\r\n        retry:\r\n          enabled: true # 开启消费者失败重试\r\n          initial-interval: 1000ms # 初始的失败等待时长为1秒\r\n          multiplier: 1 # 失败的等待时长倍数，下次等待时长 = multiplier * last-interval（类似csma-cd）\r\n          max-attempts: 3 # 最大重试次数\r\n          stateless: false # true无状态；false有状态。如果业务中包含事务，这里改为false\r\n    publisher-confirm-type: correlated # 保证消息到交换机\r\n    publisher-returns: true # 不可路由到队列的消息，回退\r\n','c0f2e7e42db6dd5eae0155d9644189de','2025-06-11 23:06:11','2025-06-11 23:06:11',NULL,'172.29.0.1','I','d53d08fa-7aab-4b26-975d-410cfc15983b',''),(3,10,'seckill-service.yml','DEFAULT_GROUP','','spring:\r\n  datasource:\r\n    username: root\r\n    password: 123456\r\n    url: jdbc:mysql://localhost:3306/seckill?serverTimezone=Asia/Shanghai&useUnicode=true&characterEncoding=utf-8&allowPublicKeyRetrieval=true&useSSL=false\r\n    driver-class-name: com.mysql.cj.jdbc.Driver\r\n\r\nmybatis:\r\n  type-aliases-package: com.lzh.entity\r\n  mapper-locations: classpath:mapper/*.xml\r\n','c884eff8589f79e7809aa457c67a4629','2025-06-11 23:43:05','2025-06-11 23:43:06',NULL,'